package com.flippingfriend.companion;
import java.util.ArrayList; import java.util.List;
/** Pure fail-closed application of PortfolioCandidate expectedProfit arithmetic. */
final class BuyReplacementExpectedProfitEvaluator {
 BuyReplacementExpectedProfitEvaluationSet evaluate(BuyReplacementUnwindLossEvaluationSet s,long at){if(s==null||at<s.getEvaluatedAt()||s.getEvaluatedAt()+CompanionBuyReplacementReadinessPolicy.MAX_INPUT_AGE_SECONDS<at||s.getEvaluations()==null||s.getEvaluations().isEmpty())return null;List<BuyReplacementExpectedProfitEvaluation> out=new ArrayList<>(s.getEvaluations().size());for(BuyReplacementUnwindLossEvaluation e:s.getEvaluations()){if(!valid(e,s))return null;double completed=e.getBuyProbability()*e.getSellProbability();double stranded=e.getBuyProbability()*(1-e.getSellProbability());double profit=completed*e.getTotalNetMargin()-stranded*e.getTotalUnwindLoss();if(!Double.isFinite(profit))return null;out.add(new BuyReplacementExpectedProfitEvaluation(e,completed,stranded,profit));}return new BuyReplacementExpectedProfitEvaluationSet(s,out,at);}
 private static boolean valid(BuyReplacementUnwindLossEvaluation e,BuyReplacementUnwindLossEvaluationSet s){return e!=null&&e.getExactRemainderQuantity()==s.getExactRemainderQuantity()&&e.getBuyPrice()>0&&e.getSellPrice()>0&&e.getTotalCost()==(long)e.getBuyPrice()*e.getExactRemainderQuantity()&&e.getTotalNetMargin()==e.getNetMarginPerItem()*e.getExactRemainderQuantity()&&e.getTotalUnwindLoss()>=0&&Double.isFinite(e.getBuyProbability())&&e.getBuyProbability()>0&&e.getBuyProbability()<=1&&Double.isFinite(e.getSellProbability())&&e.getSellProbability()>0&&e.getSellProbability()<=1&&Double.compare(e.getCompletionProbability(),e.getBuyProbability()*e.getSellProbability())==0&&Double.isFinite(e.getExpectedSlotHours())&&e.getExpectedSlotHours()>=1.0/60.0;}
}
